(()=>{const $=s=>document.querySelector(s),D=RPG_DATA,bridge=RPG_ACCOUNT_BRIDGE,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.ceil(Number(n)||0).toLocaleString('ko-KR');
const dialog=document.createElement('dialog');dialog.id='raid-dialog';dialog.className='raid-dialog';dialog.innerHTML='<div class="raid-shell"><header class="raid-header"><div><small>EXPEDITION RAID</small><h2>같이 레이드하기</h2></div><button id="raid-close" aria-label="레이드 창 닫기">×</button></header><div class="raid-scroll"><p id="raid-notice" class="raid-notice" role="status" aria-live="polite"></p><div id="raid-body"></div></div></div>';document.body.append(dialog);
const raidEffects=new RPG_RAID_EFFECTS(D);let effectFrame=performance.now();const drawPositions=new Map();const navigation=new RPG_RAID_NAVIGATION.Navigation(),movement=new RPG_RAID_NAVIGATION.Input();let paintDelta=0;let session=null,practice=null,view='',timer=null,busy=false,notice='',intent=null,stat='damage',auto=true,closed=true,owner=null,selected=null,networkErrors=0,lastRequest=0,rescueTarget=null,anim=0,epoch=0;const image=new Image();image.src='rpg-pixels-v2/dungeons/mine.png';const render=bridge.renderer;
function say(s){notice=s;$('#raid-notice').textContent=s;}
function me(){return session?.state.players.find(p=>p.id===session.you);}
function auth(){return window.RPG_ACCOUNT_UI;}
function heroList(){const payload=auth()?.account?.remote?.payload;return payload?.heroes.map((h,i)=>({...h,id:i})).filter(h=>h.recruited)||[];}
function options(){const heroes=heroList();return heroes.map(h=>`<option value="${h.id}" ${h.id===selected?'selected':''}>${esc(D.characters[h.id].name)} · ${esc(D.characters[h.id].classes[h.cell].name)} · Lv.${h.level}</option>`).join('');}
function beginPainting(){cancelAnimationFrame(anim);function frame(){if(closed)return;if($('#raid-arena'))paint();anim=requestAnimationFrame(frame);}anim=requestAnimationFrame(frame);}
function entry(){view='entry';dialog.dataset.screen='entry';const api=auth(),signed=!!api?.account?.user,heroes=heroList();if(selected===null||!heroes.some(h=>h.id===selected))selected=heroes[0]?.id??null;$('#raid-body').innerHTML=`<section class="raid-banner"><small>CO-OP RAID · CHAPTER 01</small><h3>폐광의 거신</h3><p>갈라지는 지면을 피하고, 갇힌 동료를 구출하세요.<br>거신의 핵이 열리면 함께 결정타를 날릴 시간입니다.</p><div class="raid-meta"><span>2~4인 협동</span><span>제한 시간 5분</span><span>공용 부활 2회</span></div></section>${signed?`<div class="raid-hero-select"><label for="raid-hero">함께할 캐릭터 · 클라우드 저장 기준</label><select id="raid-hero" ${heroes.length?'':'disabled'}>${options()||'<option>클라우드에 저장한 캐릭터가 없어요</option>'}</select></div>`:'<p class="raid-practice">동료와의 레이드는 구글 로그인 후 이용할 수 있어요. 혼자 연습은 바로 시작할 수 있어요.</p>'}<div class="raid-entry-grid"><section class="raid-panel"><h3>동료를 초대하세요</h3><p>방을 만들면 숫자 4자리 코드가 발급돼요.<br>같은 코드를 입력한 동료와 함께 출발하세요.</p><button class="raid-primary" data-raid="create" ${signed&&heroes.length?'':'disabled'}>방 만들기</button></section><form id="raid-join" class="raid-panel"><h3>초대 코드로 참가</h3><label for="raid-code">숫자 4자리</label><input id="raid-code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" minlength="4" autocomplete="off" placeholder="0000" required aria-label="초대 코드 숫자 4자리"><div class="raid-actions"><button type="submit" ${signed&&heroes.length?'':'disabled'}>방 참가하기</button></div></form></div><section class="raid-panel"><h3>전투 안내</h3><p>직업에 맞춘 레이드 전용 밸런스로 진행해요. 이동은 바닥을 누르거나 방향키·WASD로, 기술은 버튼 또는 1~4키로 사용할 수 있어요. 자동 전투는 사거리에 맞춰 접근해요. 위험한 바닥은 직접 피해야 해요. 직접 이동하면 3초 동안 자동 접근을 멈춰요.</p><p>실제 피해·방어·회복·구조를 기록해요. 주요 보상은 하루 3회 융합 조각 30개. 이후에는 보상 없이 계속 도전할 수 있어요. 실패 시 횟수는 차감하지 않아요. 조각 90개로 원하는 융합체 제작 · 보상마다 20% 확률로 융합체 추가 획득.</p><div class="raid-actions"><button data-raid="practice">혼자 연습 · 보상 없음</button>${signed?'':'<button data-raid="login">구글 계정 연결</button>'}</div></section>`;$('#raid-hero')?.addEventListener('change',e=>selected=Number(e.target.value));$('#raid-code').addEventListener('input',e=>e.target.value=e.target.value.replace(/[^0-9]/g,''));$('#raid-join').onsubmit=e=>{e.preventDefault();request('join',{code:$('#raid-code').value});};}
function portraits(){for(const canvas of dialog.querySelectorAll('canvas[data-hero]')){const h=D.characters[Number(canvas.dataset.hero)],cell=Number(canvas.dataset.cell);render.preload(h.sheet,cell).then(()=>{if(canvas.isConnected)render.draw(canvas.getContext('2d'),h.sheet,cell,35,75,66);}).catch(()=>{});}}
function lobby(){view='lobby';dialog.dataset.screen='lobby';$('#raid-body').innerHTML=`<section class="raid-room-heading"><div><small>PARTY ASSEMBLY</small><h3>폐광의 거신</h3><p>2~4인 · 5분 · 공용 부활 2회</p></div><canvas width="100" height="110" data-boss aria-hidden="true"></canvas></section><div class="raid-room-invite"><div><span>동료 초대 코드</span><strong>${esc(session.code)}</strong></div><button data-raid="copy">코드 복사 ↗</button></div><div class="raid-party-heading"><h4>참가 원정대 <span id="raid-party-count"></span></h4><span id="raid-party-status" aria-live="polite"></span></div><div id="raid-roster" class="raid-roster"></div><footer class="raid-room-footer"><p id="raid-room-hint"></p><div><button class="raid-subtle" data-raid="leave">방 나가기</button><button data-raid="ready">준비 완료</button>${session.host===session.you?'<button class="raid-primary" data-raid="start">출발하기 →</button>':''}</div></footer>`;render.preload('monsters/mine.png',3).then(()=>{const cn=dialog.querySelector('[data-boss]');if(cn)render.draw(cn.getContext('2d'),'monsters/mine.png',3,50,105,96);}).catch(()=>{});updateLobby();dialog.querySelector('.raid-scroll').scrollTop=0;}
function updateLobby(){if(!!dialog.querySelector('[data-raid=start]')!==(session.host===session.you)){lobby();return;}const s=session.state,p=me(),names={guard:'보호',heal:'회복',melee:'근접',ranged:'원거리'},ready=s.players.filter(x=>x.ready&&Date.now()/1000-x.seen<=15).length;$('#raid-party-count').textContent=s.players.length+'/4';$('#raid-party-status').textContent=ready+'명 준비 완료';$('#raid-room-hint').textContent=s.players.length<2?'초대 코드를 동료에게 알려주세요. 2명부터 출발할 수 있어요.':ready<s.players.length?'함께할 동료의 준비를 기다리고 있어요.':'모두 준비됐어요. 방장이 출발할 수 있어요.';const roster=$('#raid-roster');const html=Array.from({length:4},(_,i)=>{const x=s.players[i];return x?`<article class="raid-member ${x.ready?'is-ready':''} ${x.id===p.id?'is-me':''}"><div class="raid-member-top"><span>${x.id===session.host?'방장':x.id===p.id?'나':'파티원'}</span><i>${RPG_ROLE_LABELS.get(x.hero,x.cell)?.role||names[x.role]}</i></div><canvas width="70" height="78" data-hero="${x.hero}" data-cell="${x.cell}"></canvas><strong>${esc(x.name)}</strong><small>${esc(x.job)} · Lv.${x.level}</small>${RPG_ROLE_LABELS.html(x.hero,x.cell,{role:false})}<span class="raid-ready-state">${Date.now()/1000-x.seen>15?'접속 확인 중':x.ready?'✓ 준비 완료':'준비 중'}</span>${session.host===session.you&&x.id!==session.you?`<details class="raid-member-menu"><summary aria-label="${esc(x.name)} 참가자 관리">···</summary><button data-raid="kick" data-target="${i}">내보내기</button></details>`:''}</article>`:`<article class="raid-member empty"><span class="raid-empty-plus">＋</span><strong>동료 대기 중</strong><small>초대 코드로 참가</small></article>`;}).join('');if(roster.dataset.signature!==html){roster.innerHTML=html;roster.dataset.signature=html;portraits();}dialog.querySelector('[data-raid=ready]').textContent=p.ready?'✓ 준비 완료 · 취소':'준비 완료';dialog.querySelector('[data-raid=ready]').classList.toggle('is-ready',p.ready);const start=dialog.querySelector('[data-raid=start]');if(start)start.disabled=s.players.length<2||ready!==s.players.length;}
function battle(){drawPositions.clear();navigation.reset();movement.reset();raidEffects.reset(null);for(const p of session.state.players)window.RPG_VFX?.preload(p.hero,p.cell);effectFrame=performance.now();view='fight';dialog.dataset.screen='fight';$('#raid-body').innerHTML=`<div class="raid-combat-top"><div class="raid-boss-meta"><div><small>EXPEDITION BOSS</small><strong>폐광의 거신</strong></div><span id="raid-time"></span></div><div class="raid-bossbar"><i id="raid-boss-hp"></i></div><div id="raid-boss-detail"></div></div><div class="raid-battle"><canvas id="raid-arena" width="800" height="500" aria-label="레이드 전투장. 바닥을 누르면 이동합니다."></canvas><div id="raid-player-bars" class="raid-player-bars"></div><div id="raid-pattern" class="raid-pattern" aria-live="polite"></div>${session.practice?'<span class="raid-training-tag">연습 · NPC 동료 · 보상 없음</span>':''}<div id="raid-rescue"></div><div id="raid-stick" class="raid-stick" role="group" aria-label="이동 조이스틱"><i></i></div></div><footer class="raid-combat-bottom"><div class="raid-combat-options"><button data-raid="auto">자동 전투 켜짐</button><span>조이스틱 · WASD/방향키 이동 · 1~4 스킬</span><button data-raid="revive">공용 부활 2회</button></div><div id="raid-controls" class="raid-controls"></div><button class="raid-exit-combat" data-raid="${session.practice?'practice-end':'leave'}">${session.practice?'연습 기록 보기':'전투 이탈'}</button></footer>`;$('#raid-arena').addEventListener('pointerdown',e=>{const r=e.currentTarget.getBoundingClientRect(),scale=r.width/e.currentTarget.width,ox=(e.currentTarget.width-800)/2,oy=(e.currentTarget.height-500)/2;navigation.manual(session.state.t);rescueTarget=null;intent={cmd:'move',arg:{x:(e.clientX-r.left)/scale-ox,y:(e.clientY-r.top)/scale-oy}};pump();});bindStick();updateBattle();beginPainting();}
function bindStick(){const stick=$('#raid-stick');let pointer=null;const move=e=>{if(e.pointerId!==pointer)return;e.preventDefault();const box=stick.getBoundingClientRect(),radius=box.width*.34,dx=e.clientX-box.left-box.width/2,dy=e.clientY-box.top-box.height/2,len=Math.hypot(dx,dy),scale=Math.min(1,radius/Math.max(1,len));stick.style.setProperty('--stick-x',dx*scale+'px');stick.style.setProperty('--stick-y',dy*scale+'px');movement.stick(len<8?0:dx*scale/radius,len<8?0:dy*scale/radius);if(len>=8){navigation.manual(session.state.t);rescueTarget=null;}pump();};const release=e=>{if(e.pointerId!==pointer)return;pointer=null;movement.stick(null,null);stick.style.setProperty('--stick-x','0px');stick.style.setProperty('--stick-y','0px');pump();};stick.onpointerdown=e=>{pointer=e.pointerId;stick.setPointerCapture(pointer);move(e);};stick.onpointermove=move;stick.onpointerup=release;stick.onpointercancel=release;stick.onlostpointercapture=release;}

function updateBattle(){raidEffects.update(session);const s=session.state,p=me(),b=s.boss,left=Math.max(0,Math.ceil(300-s.t));$('#raid-time').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;$('#raid-boss-detail').textContent=fmt(b.hp)+' / '+fmt(b.maxHP)+' · '+Math.ceil(b.hp/b.maxHP*100)+'%';$('#raid-boss-hp').style.width=Math.max(0,b.hp/b.maxHP*100)+'%';const pattern=$('#raid-pattern'),prison=s.players.find(x=>x.prison>0),crack=b.pattern==='crack'&&b.resolveAt>s.t,core=b.exposedUntil>s.t;pattern.dataset.kind=core?'core':crack?'crack':prison?'prison':b.hp/b.maxHP<.25?'rage':'idle';pattern.innerHTML=core?`<strong>핵 노출 <b>${Math.ceil(b.exposedUntil-s.t)}</b></strong><span>지금 궁극기! 피해 +65%</span>`:crack?`<strong>균열 강타 <b>${Math.ceil(b.resolveAt-s.t)}</b></strong><span>빛나는 지면 밖으로 이동하세요</span>`:prison?`<strong>수정 감옥</strong><span>${esc(prison.id===p.id?'내가 갇혔어요!':prison.name+' 구출')} · 수정을 공격하세요</span>`:b.hp/b.maxHP<.25?'<strong>광폭화</strong><span>거신의 공격이 빨라졌어요</span>':'';$('#raid-player-bars').innerHTML=s.players.map((x,i)=>`<div class="raid-mini ${x.hp<=0?'is-down':''} ${x.id===p.id?'is-me':''}"><b>${i+1}</b><div><strong>${esc(x.name)}${x.id===p.id?' · 나':''}</strong><progress max="${x.maxHP}" value="${x.hp}" aria-label="${esc(x.name)} 체력"></progress><small>${x.hp<=0?'구조 필요':x.prison>0?'수정 감옥':Math.ceil(x.hp/x.maxHP*100)+'%'}</small></div></div>`).join('');const controls=$('#raid-controls');if(!controls.children.length)controls.innerHTML=p.skills.map((name,i)=>`<button data-raid="skill" data-slot="${i}" class="action-orb ${i===3?'raid-ultimate':''}"><kbd>${i+1}</kbd><span>${esc(D.skills.find(d=>d.heroId===p.hero&&d.cell===p.cell&&d.slot===i)?.name||name)}</span><small></small></button>`).join('');for(const button of controls.children){const slot=Number(button.dataset.slot),cd=Math.max(0,p.cooldowns[slot]-s.t);button.disabled=cd>0||p.hp<=0||p.prison>0;button.style.setProperty('--cooldown',Math.min(1,cd/(RPG_RAID_COMBAT.kit(p)?.[slot]?.cd||[5,8,13,32][slot])));button.style.setProperty('--charge',(360*(1-Math.min(1,cd/(RPG_RAID_COMBAT.kit(p)?.[slot]?.cd||[5,8,13,32][slot]))))+'deg');button.setAttribute('aria-label',p.skills[slot]+' · '+(p.hp<=0?'행동 불가':p.prison>0?'감옥에 갇힘':cd?Math.ceil(cd)+'초':'준비')); button.querySelector('small').textContent=p.hp<=0?'쓰러짐':p.prison>0?'행동 불가':cd?Math.ceil(cd)+'초':slot===3?'ULT 준비':'준비';}dialog.querySelector('[data-raid=auto]').textContent='자동 전투 '+(auto?'ON':'OFF');dialog.querySelector('[data-raid=revive]').textContent=`공용 부활 ${s.revives}회`;dialog.querySelector('[data-raid=revive]').disabled=p.hp>0||s.revives<=0;$('#raid-rescue').innerHTML=s.players.map((x,i)=>x.id!==p.id&&x.hp<=0?`<button data-raid="rescue" data-target="${i}">${esc(x.name)} ${rescueTarget===i?'구조 중 · 3초 유지':'구조하기'}</button>`:'').join('');}
function results(){view=session.state.status;dialog.dataset.screen='result';cancelAnimationFrame(anim);const s=session.state;$('#raid-body').innerHTML=`<section class="raid-result-title"><small>EXPEDITION REPORT</small><h3>${s.status==='clear'?'토벌 성공':'다음 도전을 향해'}</h3><p>폐광의 거신 · ${Math.floor(s.t/60)}분 ${Math.ceil(s.t%60)}초</p></section><div class="raid-reward">${session.practice?'연습 기록 · 보상은 저장되지 않아요':s.status==='failed'?'보상 횟수 차감 없이 다시 도전할 수 있어요':session.reward?`융합 조각 +${session.reward} · 보유 ${fmt(session.wallet)}개${session.fusionDrop?`<br>✦ ${RPG_RAID_LOOT.names[session.fusionDrop]} 획득`:``}`:'도움 참가 완료 · 주요 보상은 하루 3회예요.'}${!session.practice?`<small>오늘 보상 ${session.daily}/3회</small>`:''}</div>${!session.practice?'<button class="fusion-bag-entry" data-raid-fusion-open="1"><span>✦ 레이드 융합</span><small>보상을 전투력으로 바꾸기 →</small></button>':''}<div class="raid-result-heading"><h4>함께 남긴 기록</h4><span>실제 피해 · 방어 · 회복</span></div><div id="raid-scores"></div><footer class="raid-result-actions">${session.practice?'<button class="raid-primary" data-raid="practice">다시 연습 →</button>':session.host===session.you?'<button class="raid-primary" data-raid="retry">재도전 준비 →</button>':'<span>방장의 재도전을 기다리고 있어요.</span>'}<button data-raid="leave">돌아가기</button></footer>`;scores();dialog.querySelector('.raid-scroll').scrollTop=0;}
function scores(){const players=session.state.players,keys=['damage','defense','healing'],labels={damage:'피해량',defense:'방어량',healing:'회복량'},titles={damage:'최다 피해',defense:'수호자',healing:'치유자'},totals=Object.fromEntries(keys.map(k=>[k,players.reduce((n,p)=>n+p[k],0)])),best=Object.fromEntries(keys.map(k=>[k,players.reduce((a,p)=>p[k]>(a?.[k]||0)?p:a,null)]));$('#raid-scores').innerHTML=players.map(p=>`<article class="raid-score-all"><header><div><strong>${esc(p.name)} ${p.id===session.you?'<em>나</em>':''}</strong><small>${esc(p.job)}</small></div><div class="raid-awards">${keys.filter(k=>best[k]===p&&p[k]>0).map(k=>`<span data-stat="${k}">${titles[k]}</span>`).join('')}</div></header><div class="raid-metrics">${keys.map(k=>{const share=totals[k]?p[k]/totals[k]*100:0;return `<div data-stat="${k}"><small>${labels[k]}</small><strong>${fmt(p[k])}</strong><div class="raid-metric-bar"><i style="width:${share}%"></i></div><span>파티의 ${Math.ceil(share)}%</span></div>`;}).join('')}</div><details><summary>상세 기록 <span>구조 ${p.rescues} · 감옥 해제 ${p.mechanics}</span></summary><p>자기 방어 ${fmt(p.defense-p.allyDefense)} · 아군 보호 ${fmt(p.allyDefense)}<br>자기 회복 ${fmt(p.healing-p.allyHealing)} · 아군 회복 ${fmt(p.allyHealing)}</p></details></article>`).join('');}
function sync(){if(!session?.room){entry();return;}if(view!==session.state.status){if(session.state.status==='lobby')lobby();else if(session.state.status==='fight')battle();else results();}else if(view==='lobby')updateLobby();else if(view==='fight')updateBattle();}
async function request(cmd,arg={}){if(busy)return;busy=true;const generation=epoch;try{let data;if(practice)data=await practice.command(cmd,arg);else{const api=auth();if(!api?.account?.user)throw Error('구글 로그인이 필요해요.');const response=await api.client.rpc('rpg_raid_command',{p_cmd:cmd,p_room:session?.room||null,p_code:arg.code||null,p_hero:selected,p_arg:arg});if(response.error)throw response.error;data=response.data;if(data?.error)throw Object.assign(Error(data.error),{code:'RAID_INPUT'});}if(generation!==epoch)return;session=data;if(data?.fusion)document.dispatchEvent(new CustomEvent('rpg:raid-reward',{detail:data}));networkErrors=0;if(notice.startsWith('연결'))say('');if(cmd==='leave'){practice=null;session=null;rescueTarget=null;view='';}sync();}catch(e){if(e.code==='42501'||/참가자를 찾지|방이 만료/.test(e.message||'')){session=null;intent=null;rescueTarget=null;view='';sync();networkErrors=0;}else if(!['P0001','RAID_INPUT'].includes(e.code))networkErrors++;say(e.code==='PGRST202'?'레이드 서버를 준비 중이에요. 잠시 후 다시 입장해 주세요.':e.message||'연결을 확인하고 다시 시도해 주세요.');}finally{busy=false;lastRequest=Date.now();}}
function chooseAuto(){const p=me(),s=session.state;if(!p||p.hp<=0||p.prison>0)return null;const kit=RPG_RAID_COMBAT.kit(p),slots=p.role==='heal'?[0,1,2,3]:[0,1,2,3];for(const slot of slots){const spec=kit?.[slot];if(p.cooldowns[slot]>s.t)continue;if(spec?.supportKit&&!RPG_SUPPORT_RAID.autoReady(s,p,slot))continue;if(spec?.heal&&!s.players.some(x=>x.hp>0&&x.hp<x.maxHP*.82))continue;if(spec?.buff&&p.powerUntil>s.t+1)continue;if(['summon','dot'].includes(spec?.effect)&&(p.abilities||[]).some(a=>a.slot===slot&&a.until>s.t+3))continue;if(!spec?.supportKit&&slot===3&&s.boss.exposedUntil<=s.t&&s.boss.hp/s.boss.maxHP>.3)continue;if(['strike','dot'].includes(spec?.effect)&&Math.hypot(p.x-400,p.y-190)>spec.range)continue;return {cmd:'skill',arg:{slot}};}return null;}

async function pump(){if(closed||busy||Date.now()-lastRequest<160)return;if(networkErrors>=5){say('연결이 불안정해요. 자동으로 다시 연결하고 있어요. 창을 닫아도 같은 계정으로 복귀할 수 있어요.');}let action=intent;intent=null;if(!action&&session?.state.status==='fight'){action=movement.choose(me(),drawPositions.get(session.you));if(action){navigation.manual(session.state.t);rescueTarget=null;}}if(!action&&session?.state.status==='fight')action=rescueTarget!==null?{cmd:'rescue',arg:{target:rescueTarget}}:navigation.choose(session.state,me(),auto)||(auto?chooseAuto():null);await request(action?.cmd||'poll',action?.arg||{});}
function schedule(){clearInterval(timer);timer=setInterval(()=>{if(!closed&&session?.room)pump();},250);}
async function open(practiceOnly=false){if(practice){practice=null;session=null;}intent=null;rescueTarget=null;closed=false;epoch++;owner=auth()?.account?.user?.id||null;view='';notice='';if(!dialog.open)dialog.showModal();bridge.pause(true);say('');entry();beginPainting();if(owner&&practiceOnly!==true){await request('resume');}schedule();}
function close(){movement.reset();closed=true;epoch++;clearInterval(timer);cancelAnimationFrame(anim);intent=null;rescueTarget=null;dialog.close();bridge.pause(false);}
$('#raid-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>{if(!closed)close();});
dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-raid]');if(!b)return;const cmd=b.dataset.raid;if(cmd==='login'){close();auth()?.open();return;}if(cmd==='practice'){practice=new RPG_RAID_PRACTICE(selected??3,heroList().find(h=>h.id===selected)?.cell??3);session=await practice.command('poll');rescueTarget=null;view='';sync();schedule();return;}if(cmd==='practice-end'&&practice){practice.state.status='failed';practice.state.reason='연습 종료';session=await practice.command('poll');sync();return;}if(cmd==='auto'){auto=!auto;updateBattle();return;}if(cmd==='stat'){stat=b.dataset.stat;scores();return;}if(cmd==='copy'){try{await navigator.clipboard.writeText(session.code);say('초대 코드를 복사했어요.');}catch{say('초대 코드: '+session.code);}return;}if(cmd==='kick'){await request('kick',{target:Number(b.dataset.target)});return;}if(cmd==='rescue'){rescueTarget=Number(b.dataset.target);pump();return;}if(cmd==='skill'){intent={cmd,arg:{slot:Number(b.dataset.slot)}};pump();return;}await request(cmd);});
window.addEventListener('rpg:before-update',e=>{if(!closed&&session?.state.status==='fight'){e.preventDefault();say('새 버전이 준비됐어요. 레이드가 끝난 뒤 자동으로 반영할게요.');}});document.addEventListener('rpg:raid-open',open);document.addEventListener('rpg:account-render',()=>{if(!closed&&owner!==(auth()?.account?.user?.id||null)){session=null;practice=null;close();}});document.addEventListener('keydown',e=>{if(closed||view!=='fight'||e.target.matches('input,select,textarea')||e.ctrlKey||e.metaKey||e.altKey)return;if(movement.key(e.key,true)){e.preventDefault();navigation.manual(session.state.t);rescueTarget=null;pump();}if(/^[1-4]$/.test(e.key)&&!e.repeat){e.preventDefault();intent={cmd:'skill',arg:{slot:Number(e.key)-1}};pump();}});document.addEventListener('keyup',e=>{if(movement.key(e.key,false)&&!closed&&view==='fight'){e.preventDefault();pump();}});function resetMovement(){movement.reset();const p=me();if(!closed&&view==='fight'&&p){intent={cmd:'move',arg:{x:p.x,y:p.y}};pump();}const stick=$('#raid-stick');if(stick){stick.style.setProperty('--stick-x','0px');stick.style.setProperty('--stick-y','0px');}}window.addEventListener('blur',resetMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetMovement();});

function paint(){const now=performance.now();paintDelta=(now-effectFrame)/1000;raidEffects.step(paintDelta);effectFrame=now;const cn=$('#raid-arena'),s=session?.state;if(!cn||!s?.boss)return;const width=cn.clientWidth<600?500:Math.max(800,Math.round(cn.clientWidth/Math.max(1,cn.clientHeight)*500)),height=Math.round(cn.clientHeight/Math.max(1,cn.clientWidth)*width);if(cn.width!==width||cn.height!==height){cn.width=width;cn.height=height;}const c=cn.getContext('2d'),t=s.t+Math.min(.8,(Date.now()-lastRequest)/1000),b=s.boss;c.clearRect(0,0,cn.width,cn.height);c.imageSmoothingEnabled=false;if(image.complete&&image.naturalWidth){c.globalAlpha=.55;c.drawImage(image,0,0,cn.width,cn.height);c.globalAlpha=1;}else{c.fillStyle='#2a322a';c.fillRect(0,0,cn.width,cn.height);}c.fillStyle='#13261d66';c.fillRect(0,0,cn.width,cn.height);c.save();c.translate((cn.width-800)/2,(cn.height-500)/2);if(b.pattern==='crack'&&b.resolveAt>s.t){c.fillStyle='#f69b4a55';c.fillRect(b.lane-85,80,170,420);c.strokeStyle='#f4be7d';c.lineWidth=3;c.setLineDash([12,8]);c.strokeRect(b.lane-85,80,170,420);c.setLineDash([]);}if(b.exposedUntil>s.t){c.fillStyle='#d6ea95';c.shadowColor='#ffe19a';c.shadowBlur=28;c.beginPath();c.arc(400,150,24+Math.sin(t*8)*3,0,Math.PI*2);c.fill();c.shadowBlur=0;}render.draw(c,'monsters/mine.png',3,400,206,130,b.hp/b.maxHP<.25,.99,RPG_MOTION.pose(t,false,b.attackAt-2,-99,'fighter'));for(const serverP of [...s.players].sort((a,b)=>a.y-b.y)){const position=RPG_RAID_NAVIGATION.smooth(drawPositions.get(serverP.id),RPG_RAID_NAVIGATION.project(serverP,(Date.now()-lastRequest)/1000),paintDelta),p={...serverP,x:position.x,y:position.y};drawPositions.set(p.id,position);const h=D.characters[p.hero];const visual=raidEffects.motion(p.id);const motion=RPG_MOTION.pose(t,position.moving,p.lastAttack,p.lastCast,h.family,0,0,visual?{...visual,start:p.lastCast+visual.start}:null);render.draw(c,h.sheet,p.cell,p.x,p.y,p.hp>0?60:43,p.x>400,p.hp>0?1:.4,motion);if(p.shield>0||p.guardUntil>s.t){c.strokeStyle=p.shield>0?'#9bd7df':'#eed29b';c.lineWidth=3;c.beginPath();c.moveTo(p.x-24,p.y-8);c.lineTo(p.x-29,p.y-52);c.lineTo(p.x,p.y-70);c.lineTo(p.x+29,p.y-52);c.lineTo(p.x+24,p.y-8);c.stroke();}if(p.prison>0){c.fillStyle='#a2d6f47a';c.strokeStyle='#caf4ff';c.lineWidth=3;c.beginPath();c.moveTo(p.x,p.y-88);c.lineTo(p.x+36,p.y-40);c.lineTo(p.x+20,p.y+6);c.lineTo(p.x-24,p.y+6);c.lineTo(p.x-36,p.y-40);c.closePath();c.fill();c.stroke();}c.font='bold 13px sans-serif';c.textAlign='center';c.strokeStyle='#142219';c.lineWidth=4;c.strokeText(p.name.length>7?p.name.slice(0,7)+'…':p.name,p.x,p.y-74);c.fillStyle=p.id===session.you?'#ffdfa1':'#edf2de';c.fillText(p.name.length>7?p.name.slice(0,7)+'…':p.name,p.x,p.y-74);c.fillStyle='#10241a';c.fillRect(p.x-24,p.y+7,48,5);c.fillStyle='#b4d88e';c.fillRect(p.x-24,p.y+7,48*Math.max(0,p.hp/p.maxHP),5);}
raidEffects.paint(c,render.draw);for(const e of s.effects){if(Number.isInteger(e.slot))continue;const age=t-e.at;if(age<0||age>1.1)continue;const p=s.players.find(p=>p.id===e.owner);c.save();c.globalAlpha=Math.max(0,1-age/1.1);if(e.kind==='hit'||e.kind==='strike'){const family=p?D.characters[p.hero].family:'sword',ranged=['mage','archer','gunner','summoner','bard'].includes(family);c.strokeStyle=family==='mage'?'#95d7fa':family==='archer'?'#e6d5a4':family==='priest'?'#fff2b1':'#f7c88d';c.lineWidth=e.kind==='strike'?5:2;if(ranged&&p){const q=Math.min(1,age/.4),x=p.x+(400-p.x)*q,y=p.y-30+(150-p.y+30)*q;c.beginPath();c.moveTo(x-12,y+4);c.lineTo(x+10,y-4);c.stroke();}else{c.beginPath();c.moveTo(e.x-25,e.y-40);c.lineTo(e.x+25,e.y-15);c.moveTo(e.x-15,e.y-10);c.lineTo(e.x+20,e.y-42);c.stroke();}if(e.value){c.font='bold 19px monospace';c.fillStyle='#ffe8a2';c.fillText(fmt(e.value),e.x,e.y-65-age*35);}}else if(e.kind==='heal'){for(const q of s.players){c.fillStyle='#b0e6a0';c.fillRect(q.x-3,q.y-58-age*20,6,20);c.fillRect(q.x-10,q.y-51-age*20,20,6);}}else if(e.kind==='crack'){c.strokeStyle='#eebc6e';c.lineWidth=5;c.beginPath();for(let i=0;i<11;i++)c.lineTo(e.x+(i%2?30:-25),80+i*42);c.stroke();}c.restore();}c.restore();}
if(new URL(location.href).searchParams.get('raid')==='practice'){open(true).then(()=>dialog.querySelector('[data-raid=practice]')?.click());}
})();
